; hidden.asm -- chapter 25: blocks of one colour, and the fan
; generated by gen25.py
        INCLUDE "msx.inc"
        OUTPUT "hidden.rom"
        ORG $4000
        CART_HEADER init
VARS    EQU RAM_START + $100    ; the program's variables: the code is in ROM
        INCLUDE "bios.inc"
; WHERE IT BREAKS. Three blocks painted with the colour bytes alone, ink and
; paper of the same colour, as chapter 23 painted its plain areas; then
; fan.asm's lines drawn over them with line.
BUF     EQU $C800               ; 6,144 bytes, laid out as the patterns
BUF_H   EQU $C8
togo    EQU VARS                ; the fan's lines left to draw
init:   di
        ld sp, SYS_AREA
        VDP_REG 1, $80          ; display off while the picture is drawn
        VDP_REG 0, $02          ; Graphic II: 256 x 192 pixels (chapter 22)
        VDP_REG 2, $06          ; names              $1800
        VDP_REG 3, $FF          ; colours            $2000, 6,144 bytes
        VDP_REG 4, $03          ; patterns           $0000, 6,144 bytes
        VDP_REG 5, $36          ; sprite attributes  $1B00
        VDP_REG 6, $07          ; sprite patterns    $3800
        VDP_REG 7, $0F          ; border white
        VRAM_WRITE $0000        ; patterns: every pixel paper
        ld bc, 6144
g2p:    xor a
        out (VDP_DATA), a
        dec bc
        ld a, b
        or c
        jr nz, g2p
        VRAM_WRITE $2000        ; colours: black ink (1) on white paper (15)
        ld bc, 6144
g2c:    ld a, $1F
        out (VDP_DATA), a
        dec bc
        ld a, b
        or c
        jr nz, g2c
        VRAM_WRITE $1800        ; names: 0 to 255 in each third
        ld b, 3
g2n:    xor a
g2n1:   out (VDP_DATA), a
        inc a
        jr nz, g2n1
        djnz g2n
        VRAM_WRITE $1B00        ; no sprites
        ld a, $D0
        out (VDP_DATA), a
        ld b, 0
        ld c, 9
        ld d, 32
        ld e, 6
        ld a, $44
        call paint
        ld b, 4
        ld c, 2
        ld d, 6
        ld e, 4
        ld a, $33
        call paint
        ld b, 22
        ld c, 18
        ld d, 6
        ld e, 4
        ld a, $33
        call paint
        VDP_REG 1, $C0          ; the display on: what follows is drawn on it
go:     ld hl, ends             ; the far end of each line: x, then y
        ld a, 88
        ld (togo), a
next:   push hl
        ld b, 128               ; x0
        ld c, 96                ; y0
        ld d, (hl)              ; x1
        inc hl
        ld e, (hl)              ; y1
l0:     call line
l1:     pop hl
        inc hl
        inc hl
        ld a, (togo)
        dec a
        ld (togo), a
        jr nz, next
done:   jr done

; line: B = x0, C = y0, D = x1, E = y1: the line from (x0, y0) to (x1, y1),
;        every pixel's byte read from the VRAM, changed and written back,
;        from its top end down. Uses A, AF', BC, DE, HL.
line:   ld a, e                 ;  5
        cp c                    ;  5  y1 against y0
        jr nc, top              ; 13, or 8
        ld a, b                 ;  5  (x1, y1) is above: the ends change places
        ld b, d                 ;  5
        ld d, a                 ;  5
        ld a, c                 ;  5
        ld c, e                 ;  5
        ld e, a                 ;  5
top:    ld a, e                 ;  5
        sub c                   ;  5
        ld e, a                 ;  5  E: dy
        ld a, d                 ;  5
        sub b                   ;  5  x1 - x0
        jp c, left              ; 11  to the left
        ld d, a                 ;  5  D: dx
        call first              ; 18  HL: the byte of (x0, y0), C: its mask
        ld a, d                 ;  5
        cp e                    ;  5
        jp c, sr                ; 11  steeper than 45 degrees
fr:     ld b, d                 ;  5  flat: dx + 1 pixels
        inc b                   ;  5
        srl a                   ; 10  the error: dx / 2
        ex af, af'              ;  5
frpx:   ld a, l                 ;  5
        out (VDP_CTRL), a       ; 12  the read address
        ld a, h                 ;  5
        out (VDP_CTRL), a       ; 12  ... and the VDP reads the byte ahead
        ex af, af'              ;  5  while it reads, the error,
        sub e                   ;  5  less dy: carry, below zero,
        ex af, af'              ;  5  kept with its carry
        nop                     ;  5  29 T-states from the address to the IN
        in a, (VDP_DATA)        ; 12  the byte
        or c                    ;  5  and the pixel
        push af                 ; 12
        ld a, l                 ;  5
        out (VDP_CTRL), a       ; 12  the write address
        ld a, h                 ;  5
        or $40                  ;  8
        out (VDP_CTRL), a       ; 12
        pop af                  ; 11
        out (VDP_DATA), a       ; 12  the byte, with the pixel
        rrc c                   ; 10  a pixel right:
        jr nc, frsm             ; 13, or 8  in the same byte, or
        ld a, l                 ;  5  in the next, 8 on
        add a, 8                ;  8
        ld l, a                 ;  5
frsm:   ex af, af'              ;  5  the error, and its carry
        jr c, frdn              ; 13, or 8
        ex af, af'              ;  5
        djnz frpx               ; 14, or 9
        ret                     ; 11
frdn:   add a, d                ;  5  below zero: dx back,
        ex af, af'              ;  5
        inc l                   ;  5  and a line down (chapter 22's down)
        ld a, l                 ;  5
        and 7                   ;  8
        jr nz, frnx             ; 13, or 8
        ld a, l                 ;  5
        sub 8                   ;  8
        ld l, a                 ;  5
        inc h                   ;  5
frnx:   djnz frpx               ; 14, or 9
        ret                     ; 11
sr:     ld b, e                 ;  5  steep: dy + 1 pixels
        inc b                   ;  5
        ld a, e                 ;  5
        srl a                   ; 10  the error: dy / 2
        ex af, af'              ;  5
srpx:   ld a, l                 ;  5
        out (VDP_CTRL), a       ; 12  the read address
        ld a, h                 ;  5
        out (VDP_CTRL), a       ; 12  ... and the VDP reads the byte ahead
        ex af, af'              ;  5  while it reads, the error,
        sub d                   ;  5  less dx: carry, below zero,
        ex af, af'              ;  5  kept with its carry
        nop                     ;  5  29 T-states from the address to the IN
        in a, (VDP_DATA)        ; 12  the byte
        or c                    ;  5  and the pixel
        push af                 ; 12
        ld a, l                 ;  5
        out (VDP_CTRL), a       ; 12  the write address
        ld a, h                 ;  5
        or $40                  ;  8
        out (VDP_CTRL), a       ; 12
        pop af                  ; 11
        out (VDP_DATA), a       ; 12  the byte, with the pixel
        inc l                   ;  5  a line down (chapter 22's down)
        ld a, l                 ;  5
        and 7                   ;  8
        jr nz, srsm             ; 13, or 8
        ld a, l                 ;  5
        sub 8                   ;  8
        ld l, a                 ;  5
        inc h                   ;  5
srsm:   ex af, af'              ;  5  the error, and its carry
        jr c, srdn              ; 13, or 8
        ex af, af'              ;  5
        djnz srpx               ; 14, or 9
        ret                     ; 11
srdn:   add a, e                ;  5  below zero: dy back,
        ex af, af'              ;  5
        rrc c                   ; 10  and a pixel right:
        jr nc, srnx             ; 13, or 8  in the same byte, or
        ld a, l                 ;  5  in the next, 8 on
        add a, 8                ;  8
        ld l, a                 ;  5
srnx:   djnz srpx               ; 14, or 9
        ret                     ; 11
left:   neg                     ; 10  to the left: dx = x0 - x1
        ld d, a                 ;  5  D: dx
        call first              ; 18
        ld a, d                 ;  5
        cp e                    ;  5
        jp c, sl                ; 11
fl:     ld b, d                 ;  5  flat: dx + 1 pixels
        inc b                   ;  5
        srl a                   ; 10  the error: dx / 2
        ex af, af'              ;  5
flpx:   ld a, l                 ;  5
        out (VDP_CTRL), a       ; 12  the read address
        ld a, h                 ;  5
        out (VDP_CTRL), a       ; 12  ... and the VDP reads the byte ahead
        ex af, af'              ;  5  while it reads, the error,
        sub e                   ;  5  less dy: carry, below zero,
        ex af, af'              ;  5  kept with its carry
        nop                     ;  5  29 T-states from the address to the IN
        in a, (VDP_DATA)        ; 12  the byte
        or c                    ;  5  and the pixel
        push af                 ; 12
        ld a, l                 ;  5
        out (VDP_CTRL), a       ; 12  the write address
        ld a, h                 ;  5
        or $40                  ;  8
        out (VDP_CTRL), a       ; 12
        pop af                  ; 11
        out (VDP_DATA), a       ; 12  the byte, with the pixel
        rlc c                   ; 10  a pixel left:
        jr nc, flsm             ; 13, or 8  in the same byte, or
        ld a, l                 ;  5  in the next, 8 back
        sub 8                   ;  8
        ld l, a                 ;  5
flsm:   ex af, af'              ;  5  the error, and its carry
        jr c, fldn              ; 13, or 8
        ex af, af'              ;  5
        djnz flpx               ; 14, or 9
        ret                     ; 11
fldn:   add a, d                ;  5  below zero: dx back,
        ex af, af'              ;  5
        inc l                   ;  5  and a line down (chapter 22's down)
        ld a, l                 ;  5
        and 7                   ;  8
        jr nz, flnx             ; 13, or 8
        ld a, l                 ;  5
        sub 8                   ;  8
        ld l, a                 ;  5
        inc h                   ;  5
flnx:   djnz flpx               ; 14, or 9
        ret                     ; 11
sl:     ld b, e                 ;  5  steep: dy + 1 pixels
        inc b                   ;  5
        ld a, e                 ;  5
        srl a                   ; 10  the error: dy / 2
        ex af, af'              ;  5
slpx:   ld a, l                 ;  5
        out (VDP_CTRL), a       ; 12  the read address
        ld a, h                 ;  5
        out (VDP_CTRL), a       ; 12  ... and the VDP reads the byte ahead
        ex af, af'              ;  5  while it reads, the error,
        sub d                   ;  5  less dx: carry, below zero,
        ex af, af'              ;  5  kept with its carry
        nop                     ;  5  29 T-states from the address to the IN
        in a, (VDP_DATA)        ; 12  the byte
        or c                    ;  5  and the pixel
        push af                 ; 12
        ld a, l                 ;  5
        out (VDP_CTRL), a       ; 12  the write address
        ld a, h                 ;  5
        or $40                  ;  8
        out (VDP_CTRL), a       ; 12
        pop af                  ; 11
        out (VDP_DATA), a       ; 12  the byte, with the pixel
        inc l                   ;  5  a line down (chapter 22's down)
        ld a, l                 ;  5
        and 7                   ;  8
        jr nz, slsm             ; 13, or 8
        ld a, l                 ;  5
        sub 8                   ;  8
        ld l, a                 ;  5
        inc h                   ;  5
slsm:   ex af, af'              ;  5  the error, and its carry
        jr c, sldn              ; 13, or 8
        ex af, af'              ;  5
        djnz slpx               ; 14, or 9
        ret                     ; 11
sldn:   add a, e                ;  5  below zero: dy back,
        ex af, af'              ;  5
        rlc c                   ; 10  and a pixel left:
        jr nc, slnx             ; 13, or 8  in the same byte, or
        ld a, l                 ;  5  in the next, 8 back
        sub 8                   ;  8
        ld l, a                 ;  5
slnx:   djnz slpx               ; 14, or 9
        ret                     ; 11

; first: B = x, C = y -> HL: the byte of pixel (x, y), C: its mask
first:  call vaddr              ; 18
        ld a, b                 ;  5
        and 7                   ;  8
        ld c, a                 ;  5
        ld b, high masks        ;  8
        ld a, (bc)              ;  8
        ld c, a                 ;  5
        ret                     ; 11

; paint: B = the first column of cells, C = the first row, D = the columns,
;        E = the rows, A = a colour byte: the colours of a block of whole
;        cells. The display is off.
paint:  ld h, a                 ; H: the colour byte
prow:   push bc
        push de
pcell:  ld a, b                 ; the cell's eight colour bytes: column x 8,
        add a, a
        add a, a
        add a, a
        out (VDP_CTRL), a
        ld a, c                 ; and the row, of the colours ($2000)
        or $60
        out (VDP_CTRL), a
        ld a, h
        ld l, 8
pbyte:  out (VDP_DATA), a
        dec l
        jr nz, pbyte
        inc b
        dec d
        jr nz, pcell
        pop de
        pop bc
        inc c
        dec e
        jr nz, prow
        ret

; vaddr: B = x, C = y -> HL = the address of the byte that holds pixel (x, y),
; in the patterns of a Graphic II screen whose names run 0 to 255 in each
; third (chapter 22). Uses A.
vaddr:  ld a, c                 ;  5
        rrca                    ;  5
        rrca                    ;  5
        rrca                    ;  5
        and $1F                 ;  8: y / 8, the row of characters
        ld h, a                 ;  5
        ld a, b                 ;  5
        and $F8                 ;  8: the column of characters, x 8
        ld l, a                 ;  5
        ld a, c                 ;  5
        and 7                   ;  8: the line in the cell
        or l                    ;  5
        ld l, a                 ;  5
        ret                     ; 11
ends:
        db 40, 8
        db 48, 8
        db 56, 8
        db 64, 8
        db 72, 8
        db 80, 8
        db 88, 8
        db 96, 8
        db 104, 8
        db 112, 8
        db 120, 8
        db 128, 8
        db 136, 8
        db 144, 8
        db 152, 8
        db 160, 8
        db 168, 8
        db 176, 8
        db 184, 8
        db 192, 8
        db 200, 8
        db 208, 8
        db 216, 8
        db 216, 16
        db 216, 24
        db 216, 32
        db 216, 40
        db 216, 48
        db 216, 56
        db 216, 64
        db 216, 72
        db 216, 80
        db 216, 88
        db 216, 96
        db 216, 104
        db 216, 112
        db 216, 120
        db 216, 128
        db 216, 136
        db 216, 144
        db 216, 152
        db 216, 160
        db 216, 168
        db 216, 176
        db 216, 184
        db 208, 184
        db 200, 184
        db 192, 184
        db 184, 184
        db 176, 184
        db 168, 184
        db 160, 184
        db 152, 184
        db 144, 184
        db 136, 184
        db 128, 184
        db 120, 184
        db 112, 184
        db 104, 184
        db 96, 184
        db 88, 184
        db 80, 184
        db 72, 184
        db 64, 184
        db 56, 184
        db 48, 184
        db 40, 184
        db 40, 176
        db 40, 168
        db 40, 160
        db 40, 152
        db 40, 144
        db 40, 136
        db 40, 128
        db 40, 120
        db 40, 112
        db 40, 104
        db 40, 96
        db 40, 88
        db 40, 80
        db 40, 72
        db 40, 64
        db 40, 56
        db 40, 48
        db 40, 40
        db 40, 32
        db 40, 24
        db 40, 16

        ALIGN 256
masks:  db $80, $40, $20, $10, $08, $04, $02, $01 ; pixel n of a byte: bit 7 - n
        ASSERT $ <= $8000, the program is longer than the cartridge
        ds $8000 - $, $FF       ; pad the cartridge to 16 KB
